pub struct ContextData {
    pub contract: Contract,
    pub package: PathBuf,
    pub root: PathBuf,
    pub config_path: PathBuf,
    pub value: Value,
    pub data_dir: PathBuf,
}

pub fn normalized(path: &Path) -> anyhow::Result<()> {
    ensure!(
        path.is_absolute()
            && path != Path::new("/")
            && path
                .to_str()
                .is_some_and(|name| !name.chars().any(char::is_control)),
        "path must be an absolute UTF-8 non-root path"
    );
    ensure!(
        path.components()
            .all(|part| matches!(part, Component::RootDir | Component::Normal(_)))
            && path.components().collect::<PathBuf>().as_os_str() == path.as_os_str(),
        "path must be normalized"
    );
    let mut prefix = PathBuf::new();
    for part in path.components() {
        prefix.push(part);
        match fs::symlink_metadata(&prefix) {
            Ok(info) => ensure!(
                !info.file_type().is_symlink(),
                "path aliases are not accepted"
            ),
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => {}
            Err(error) => return Err(error.into()),
        }
    }
    Ok(())
}

pub fn read(path: &Path, maximum: u64) -> anyhow::Result<Vec<u8>> {
    normalized(path)?;
    let mut file = OpenOptions::new()
        .read(true)
        .custom_flags((rustix::fs::OFlags::NOFOLLOW | rustix::fs::OFlags::NONBLOCK).bits() as i32)
        .open(path)?;
    let before = file.metadata()?;
    ensure!(
        before.is_file() && before.nlink() == 1 && before.len() <= maximum,
        "file type, links or size exceeds contract"
    );
    let mut bytes = Vec::new();
    file.by_ref().take(maximum + 1).read_to_end(&mut bytes)?;
    let after = file.metadata()?;
    ensure!(
        bytes.len() as u64 <= maximum
            && before.dev() == after.dev()
            && before.ino() == after.ino()
            && before.len() == after.len()
            && before.mtime() == after.mtime()
            && before.mtime_nsec() == after.mtime_nsec()
            && before.ctime() == after.ctime()
            && before.ctime_nsec() == after.ctime_nsec(),
        "file changed during bounded read"
    );
    Ok(bytes)
}

fn hash(bytes: &[u8]) -> String {
    Sha256::digest(bytes)
        .iter()
        .map(|byte| format!("{byte:02x}"))
        .collect()
}
fn relative(value: &str) -> anyhow::Result<&Path> {
    let path = Path::new(value);
    ensure!(
        !value.is_empty()
            && !path.is_absolute()
            && path
                .components()
                .all(|part| matches!(part, Component::Normal(_)))
            && path.components().collect::<PathBuf>().as_os_str() == path.as_os_str(),
        "material path must be a normalized relative path"
    );
    Ok(path)
}

impl ContextData {
    pub fn load(
        product: &str,
        root: &Path,
        config: &Path,
        allow_missing_config: bool,
    ) -> anyhow::Result<Self> {
        normalized(root)?;
        normalized(config)?;
        let executable = std::env::current_exe()?;
        let package = executable
            .parent()
            .and_then(Path::parent)
            .context("setup package root is missing")?
            .to_path_buf();
        Self::from_package(&package, product, root, config, allow_missing_config)
    }
    pub fn from_package(
        package: &Path,
        product: &str,
        root: &Path,
        config: &Path,
        allow_missing_config: bool,
    ) -> anyhow::Result<Self> {
        normalized(package)?;
        let manifest: Manifest =
            crate::strict_json::decode(&read(&package.join("share/package.json"), 1024 * 1024)?)?;
        let digest = read(&package.join("share/package.sha256"), 65)?;
        let digest = std::str::from_utf8(&digest)?;
        ensure!(
            digest.len() == 65
                && digest.ends_with('\n')
                && digest[..64]
                    .bytes()
                    .all(|byte| byte.is_ascii_digit() || (b'a'..=b'f').contains(&byte)),
            "package manifest SHA256 declaration differs"
        );
        ensure!(
            digest[..64] == hash(&read(&package.join("share/package.json"), 1024 * 1024)?),
            "package manifest SHA256 differs"
        );
        ensure!(
            manifest.manifest_version == 1 && manifest.identity.product == product,
            "material package product or format differs"
        );
        manifest.identity.validate()?;
        manifest.schema_identity.validate()?;
        let material = package.join("share/contracts/install.json");
        let bytes = read(&material, 1024 * 1024)?;
        let declared = manifest
            .files
            .iter()
            .find(|entry| entry.path == "share/contracts/install.json")
            .context("installation material is not in verified inventory")?;
        ensure!(
            declared.size == bytes.len() as u64 && declared.sha256 == hash(&bytes),
            "installation material differs from package inventory"
        );
        let raw: Value = crate::strict_json::decode(&bytes)?;
        let material_schema: Value =
            serde_json::from_str(include_str!("../scripts/install-contract.schema.json"))?;
        let validator = jsonschema::options()
            .should_validate_formats(true)
            .build(&material_schema)?;
        ensure!(
            validator.is_valid(&raw),
            "installation material violates current contract"
        );
        let contract: Contract = serde_json::from_value(raw)?;
        ensure!(
            contract.contract_version == 1
                && contract.identity == manifest.identity
                && contract.schema_identity == manifest.schema_identity,
            "installation material identity differs"
        );
        ensure!(
            !contract.authority_sources.is_empty()
                && !contract.databases.is_empty()
                && !contract.writers.is_empty(),
            "installation material lacks required current definitions"
        );
        for database in &contract.databases {
            verify_asset(package, &manifest, &database.ddl)?;
        }
        if let Some(media) = &contract.media {
            for asset in [&media.template, &media.binary, &media.contract] {
                verify_asset(package, &manifest, asset)?;
            }
        }
        let mut supplied = match read(config, 1024 * 1024) {
            Ok(bytes) => crate::strict_json::decode(&bytes)?,
            Err(error)
                if allow_missing_config
                    && fs::symlink_metadata(config)
                        .is_err_and(|error| error.kind() == std::io::ErrorKind::NotFound) =>
            {
                let _ = error;
                Value::Object(serde_json::Map::new())
            }
            Err(error) => return Err(error),
        };
        let mut value = contract.config.defaults.clone();
        render_root(&mut value, root)?;
        merge(&mut value, &mut supplied)?;
        let data_dir = resolve(&contract.config.data_dir, &value, root)?;
        let context = Self {
            contract,
            package: package.to_owned(),
            root: root.to_owned(),
            config_path: config.to_owned(),
            value,
            data_dir,
        };
        context.validate_config()?;
        Ok(context)
    }
    pub fn path(&self, spec: &PathSpec) -> anyhow::Result<PathBuf> {
        resolve(spec, &self.value, &self.root)
    }
    pub fn asset(&self, asset: &Asset) -> anyhow::Result<Vec<u8>> {
        let bytes = read(&self.package.join(relative(&asset.path)?), 16 * 1024 * 1024)?;
        ensure!(
            hash(&bytes) == asset.sha256,
            "material asset digest differs"
        );
        Ok(bytes)
    }
    pub fn validate_config(&self) -> anyhow::Result<()> {
        let validator = jsonschema::options()
            .should_validate_formats(true)
            .build(&self.contract.config.schema)?;
        ensure!(
            validator.is_valid(&self.value),
            "configuration violates generated schema"
        );
        for case in &self.contract.config.cases {
            let mut supplied = case.value.clone();
            render_root(&mut supplied, &self.root)?;
            let mut value = self.contract.config.defaults.clone();
            render_root(&mut value, &self.root)?;
            merge(&mut value, &mut supplied)?;
            ensure!(
                (validator.is_valid(&value)
                    && self
                        .contract
                        .config
                        .rules
                        .iter()
                        .all(|rule| validate_rule(rule, &value, &self.root).is_ok()))
                    == case.valid,
                "configuration schema disagrees with validation example {}",
                case.name
            );
        }
        for rule in &self.contract.config.rules {
            validate_rule(rule, &self.value, &self.root)?;
        }
        Ok(())
    }
    pub fn report(&self, initialized: bool) -> anyhow::Result<Value> {
        let paths = |specs: &[PathSpec]| -> anyhow::Result<Vec<PathBuf>> {
            let mut paths = specs
                .iter()
                .map(|spec| self.path(spec))
                .collect::<anyhow::Result<Vec<_>>>()?;
            paths.sort();
            paths.dedup();
            Ok(paths)
        };
        let mut state = paths(&self.contract.resources.state_paths)?;
        let all = state.clone();
        state.retain(|path| {
            !all.iter()
                .any(|parent| path != parent && path.starts_with(parent))
        });
        let mut private_files = self
            .contract
            .databases
            .iter()
            .map(|database| self.path(&database.path))
            .chain(
                self.contract
                    .secrets
                    .iter()
                    .map(|secret| self.path(&secret.path)),
            )
            .collect::<anyhow::Result<Vec<_>>>()?;
        if let Some(media) = &self.contract.media {
            private_files.push(self.path(&media.configuration_path)?);
        }
        private_files.extend(
            self.contract
                .resources
                .runtime_locks
                .iter()
                .filter(|lock| lock.kind == "file")
                .map(|lock| self.path(&lock.path))
                .collect::<anyhow::Result<Vec<_>>>()?,
        );
        let runtime_locks = self
            .contract
            .resources
            .runtime_locks
            .iter()
            .map(|lock| -> anyhow::Result<Value> {
                ensure!(
                    matches!(lock.kind.as_str(), "file" | "directory"),
                    "unsupported runtime lock kind"
                );
                let path = self.path(&lock.path)?;
                if lock.kind == "directory" {
                    ensure!(
                        self.contract
                            .resources
                            .business_paths
                            .iter()
                            .chain(&self.contract.resources.shared_paths)
                            .any(|spec| self.path(spec).is_ok_and(|declared| declared == path)),
                        "directory lock is not an exact declared business root"
                    );
                }
                Ok(serde_json::json!({"path":path,"kind":lock.kind}))
            })
            .collect::<anyhow::Result<Vec<_>>>()?;
        private_files.sort();
        private_files.dedup();
        for business in paths(&self.contract.resources.business_paths)? {
            ensure!(
                private_files.iter().all(
                    |private| !business.starts_with(private) && !private.starts_with(&business)
                ),
                "business root overlaps declared private file"
            );
        }
        for directory in paths(&self.contract.resources.business_directories)? {
            ensure!(
                self.contract
                    .resources
                    .business_paths
                    .iter()
                    .any(|spec| self
                        .path(spec)
                        .is_ok_and(|root| directory != root && directory.starts_with(root))),
                "business directory is not a strict declared business child"
            );
            ensure!(
                private_files
                    .iter()
                    .all(|file| !directory.starts_with(file) && !file.starts_with(&directory)),
                "business directory overlaps private file"
            );
        }
        let bind = self
            .value
            .pointer(&self.contract.config.bind_pointer)
            .and_then(Value::as_str)
            .context("bind address is missing")?;
        let _: std::net::SocketAddr = bind.parse()?;
        Ok(
            serde_json::json!({"product":self.contract.identity.product,"root":self.root,"data_dir":self.data_dir,"schema_identity":self.contract.schema_identity,"bind":bind,"state_paths":state,"runtime_locks":runtime_locks,"private_files":private_files,"private_directories":paths(&self.contract.resources.private_directories)?,"business_directories":paths(&self.contract.resources.business_directories)?,"writable_paths":paths(&self.contract.resources.writable_paths)?,"readonly_paths":paths(&self.contract.resources.readonly_paths)?,"config_write_paths":paths(&self.contract.resources.config_write_paths)?,"shared_paths":paths(&self.contract.resources.shared_paths)?,"business_paths":paths(&self.contract.resources.business_paths)?,"initialized":initialized}),
        )
    }
}

fn verify_asset(package: &Path, manifest: &Manifest, asset: &Asset) -> anyhow::Result<()> {
    let path = relative(&asset.path)?;
    let declared = manifest
        .files
        .iter()
        .find(|entry| entry.path == asset.path)
        .context("material asset is absent from verified inventory")?;
    ensure!(
        declared.sha256 == asset.sha256,
        "material and inventory asset digest differ"
    );
    let bytes = read(&package.join(path), 512 * 1024 * 1024)?;
    ensure!(
        declared.size == bytes.len() as u64 && hash(&bytes) == asset.sha256,
        "material asset bytes differ"
    );
    Ok(())
}

pub fn resolve(spec: &PathSpec, value: &Value, root: &Path) -> anyhow::Result<PathBuf> {
    resolve_at(spec, value, root, 0)
}
fn resolve_at(
    spec: &PathSpec,
    value: &Value,
    root: &Path,
    depth: usize,
) -> anyhow::Result<PathBuf> {
    ensure!(depth < 16, "path fallback nesting exceeds limit");
    let text = match spec.base.as_str() {
        "root" => Some(spec.value.as_str()),
        "config" => match value.pointer(&spec.value) {
            Some(Value::String(value)) => Some(value.as_str()),
            None | Some(Value::Null) => None,
            _ => anyhow::bail!("declared configuration path must be text or null"),
        },
        _ => anyhow::bail!("unknown path source"),
    };
    let path = if let Some(text) = text {
        let text = match spec.encoding.as_str() {
            "path" | "sibling-lock" => text,
            "sqlite-url" | "sqlite-sibling-lock" => text
                .strip_prefix("sqlite://")
                .filter(|text| !text.contains(['?', '#']))
                .context("database URL must identify a local current file")?,
            _ => anyhow::bail!("unknown path encoding"),
        };
        if spec.base == "root" {
            root.join(relative(text)?)
        } else if Path::new(text).is_absolute() {
            PathBuf::from(text)
        } else {
            root.join(text)
        }
    } else {
        resolve_at(
            spec.fallback
                .as_ref()
                .context("declared configuration path is missing")?,
            value,
            root,
            depth + 1,
        )?
    };
    let path = if matches!(
        spec.encoding.as_str(),
        "sibling-lock" | "sqlite-sibling-lock"
    ) {
        ensure!(
            !spec.suffix.is_empty()
                && !spec.suffix.contains('/')
                && !spec.suffix.chars().any(char::is_control),
            "sibling lock suffix invalid"
        );
        path.parent()
            .context("sibling lock parent missing")?
            .join(format!(
                ".{}{}",
                path.file_name()
                    .and_then(|name| name.to_str())
                    .context("sibling lock basename missing")?,
                spec.suffix
            ))
    } else if spec.suffix.is_empty() {
        path
    } else {
        path.join(relative(&spec.suffix)?)
    };
    normalized(&path)?;
    Ok(path)
}

fn render_root(value: &mut Value, root: &Path) -> anyhow::Result<()> {
    match value {
        Value::String(text) => {
            if text == "$ROOT" {
                *text = root.to_str().context("root must be UTF-8")?.to_owned()
            } else if let Some(suffix) = text.strip_prefix("$ROOT/") {
                *text = root
                    .join(suffix)
                    .to_str()
                    .context("root path must be UTF-8")?
                    .to_owned()
            } else if let Some(suffix) = text.strip_prefix("sqlite://$ROOT/") {
                *text = format!("sqlite://{}", root.join(suffix).display())
            }
        }
        Value::Array(values) => {
            for value in values {
                render_root(value, root)?
            }
        }
        Value::Object(values) => {
            for value in values.values_mut() {
                render_root(value, root)?
            }
        }
        _ => {}
    };
    Ok(())
}

pub fn validate_rule(rule: &Rule, value: &Value, root: &Path) -> anyhow::Result<()> {
    let args = rule
        .arguments
        .as_object()
        .context("semantic arguments must be an object")?;
    let keys = |allowed: &[&str]| -> anyhow::Result<()> {
        ensure!(
            args.keys().all(|key| allowed.contains(&key.as_str())),
            "unknown semantic argument"
        );
        Ok(())
    };
    let fields = |expected: usize| -> anyhow::Result<()> {
        ensure!(
            rule.fields.len() == expected,
            "semantic field count differs"
        );
        Ok(())
    };
    let flag = |name: &str, default: bool| -> anyhow::Result<bool> {
        args.get(name).map_or(Ok(default), |value| {
            value.as_bool().context("semantic flag must be boolean")
        })
    };
    let text = |name: &str| -> anyhow::Result<&str> {
        args.get(name)
            .and_then(Value::as_str)
            .context("semantic argument must be text")
    };
    let number = |name: &str| -> anyhow::Result<u64> {
        args.get(name)
            .and_then(Value::as_u64)
            .context("semantic argument must be unsigned integer")
    };
    let candidate = |pointer: &str| -> anyhow::Result<&Value> {
        value.pointer(pointer).context("semantic field missing")
    };
    let unsigned = |pointer: &str| -> anyhow::Result<u64> {
        candidate(pointer)?
            .as_u64()
            .context("semantic field must be unsigned integer")
    };
    match rule.kind.as_str() {
        "integer-range" => {
            fields(1)?;
            keys(&["minimum", "maximum"])?;
            let min = number("minimum")?;
            let max = number("maximum")?;
            ensure!(
                min <= max && (min..=max).contains(&unsigned(&rule.fields[0])?),
                "integer outside semantic range"
            );
        }
        "integer-order" => {
            fields(2)?;
            keys(&["relation", "left_scale", "right_scale"])?;
            let scale = |name: &str| -> anyhow::Result<u64> {
                let scale = args.get(name).map_or(Ok(1), |v| {
                    v.as_u64().context("scale must be unsigned integer")
                })?;
                ensure!(scale > 0, "scale must be positive");
                Ok(scale)
            };
            let left = unsigned(&rule.fields[0])?
                .checked_mul(scale("left_scale")?)
                .context("integer scale overflow")?;
            let right = unsigned(&rule.fields[1])?
                .checked_mul(scale("right_scale")?)
                .context("integer scale overflow")?;
            ensure!(
                match text("relation")? {
                    "less-than" => left < right,
                    "less-or-equal" => left <= right,
                    _ => anyhow::bail!("unknown integer relation"),
                },
                "integer semantic order differs"
            );
        }
        "integer-sum-order" => {
            keys(&["relation"])?;
            ensure!(
                (3..=16).contains(&rule.fields.len()),
                "sum order field count differs"
            );
            let (right, terms) = rule.fields.split_last().context("sum fields missing")?;
            let left = terms
                .iter()
                .try_fold(0u64, |sum, term| -> anyhow::Result<u64> {
                    sum.checked_add(unsigned(term)?)
                        .context("integer sum overflow")
                })?;
            let right = unsigned(right)?;
            ensure!(
                match text("relation")? {
                    "less-than" => left < right,
                    "less-or-equal" => left <= right,
                    _ => anyhow::bail!("unknown integer relation"),
                },
                "integer semantic sum order differs"
            );
        }
        "path-equals" => {
            fields(1)?;
            keys(&["expected"])?;
            let expected: PathSpec = serde_json::from_value(
                args.get("expected")
                    .context("expected path missing")?
                    .clone(),
            )?;
            let expected = resolve(&expected, value, root)?;
            let actual = Path::new(
                candidate(&rule.fields[0])?
                    .as_str()
                    .context("path must be text")?,
            );
            normalized(actual)?;
            ensure!(actual == expected, "path differs from owned contract");
        }
        "token-template" => {
            fields(1)?;
            keys(&[
                "maximum_bytes",
                "maximum_tokens",
                "marker",
                "variables",
                "header_prefix",
                "header_name_encoding",
            ])?;
            let maximum_bytes = number("maximum_bytes")?;
            let maximum_tokens = number("maximum_tokens")?;
            ensure!(
                (1..=1024 * 1024).contains(&maximum_bytes) && (1..=16384).contains(&maximum_tokens),
                "template limits exceed supported budgets"
            );
            ensure!(
                text("marker")? == "$"
                    && text("header_name_encoding")? == "ascii-lowercase-underscore-to-hyphen",
                "unsupported template grammar"
            );
            let variables = args
                .get("variables")
                .and_then(Value::as_array)
                .context("template variables missing")?;
            let header = text("header_prefix")?;
            ensure!(
                !header.is_empty()
                    && header
                        .bytes()
                        .all(|b| b.is_ascii_alphanumeric() || b == b'_')
                    && variables.len() <= 256,
                "invalid template variable declarations"
            );
            let mut known = std::collections::BTreeSet::new();
            for value in variables {
                let variable = value.as_str().context("template variable must be text")?;
                ensure!(
                    !variable.is_empty()
                        && variable
                            .bytes()
                            .all(|b| b.is_ascii_alphanumeric() || b == b'_')
                        && known.insert(variable),
                    "template variables are malformed or repeat"
                );
            }
            let input = candidate(&rule.fields[0])?
                .as_str()
                .context("template must be text")?;
            ensure!(
                input.len() as u64 <= maximum_bytes,
                "template exceeds byte limit"
            );
            let mut position = 0;
            let mut count = 0u64;
            while position < input.len() {
                let next = input[position..]
                    .find('$')
                    .map_or(input.len(), |offset| position + offset);
                if next > position {
                    count += 1;
                }
                if next == input.len() {
                    break;
                }
                let start = next + 1;
                let end = input[start..]
                    .char_indices()
                    .find(|(_, c)| !(c.is_alphanumeric() || *c == '_'))
                    .map_or(input.len(), |(offset, _)| start + offset);
                let name = &input[start..end];
                let valid_header = name.strip_prefix(header).is_some_and(|value| {
                    !value.is_empty()
                        && value
                            .bytes()
                            .all(|b| b.is_ascii_alphanumeric() || b == b'_')
                });
                ensure!(
                    known.contains(name) || valid_header,
                    "unknown or malformed template variable"
                );
                count += 1;
                position = end;
                ensure!(count <= maximum_tokens, "template exceeds token limit");
            }
            ensure!(count <= maximum_tokens, "template exceeds token limit");
        }
        "socket-address" => {
            fields(1)?;
            keys(&["nonzero", "loopback", "loopback_when"])?;
            let actual: std::net::SocketAddr = candidate(&rule.fields[0])?
                .as_str()
                .context("socket must be text")?
                .parse()?;
            let conditional = match args.get("loopback_when") {
                None | Some(Value::Null) => false,
                Some(Value::String(pointer)) => candidate(pointer)?
                    .as_bool()
                    .context("loopback condition must be boolean")?,
                _ => anyhow::bail!("invalid loopback condition"),
            };
            ensure!(
                !(flag("nonzero", false)? && actual.port() == 0)
                    && !((flag("loopback", false)? || conditional) && !actual.ip().is_loopback()),
                "socket violates semantic restrictions"
            );
        }
        "distinct-sockets" => {
            keys(&[])?;
            ensure!(
                rule.fields.len() >= 2,
                "distinct sockets require multiple fields"
            );
            let mut sockets = Vec::new();
            for pointer in &rule.fields {
                let address: std::net::SocketAddr = candidate(pointer)?
                    .as_str()
                    .context("socket must be text")?
                    .parse()?;
                ensure!(
                    !sockets
                        .iter()
                        .any(
                            |other: &std::net::SocketAddr| other.port() == address.port()
                                && (other.ip() == address.ip()
                                    || other.ip().is_unspecified()
                                    || address.ip().is_unspecified())
                        ),
                    "socket listeners overlap"
                );
                sockets.push(address);
            }
        }
        "path" => {
            fields(1)?;
            keys(&["optional", "absolute"])?;
            let actual = candidate(&rule.fields[0])?;
            if actual.is_null() && flag("optional", false)? {
                return Ok(());
            }
            let path = Path::new(actual.as_str().context("path must be text")?);
            ensure!(
                !flag("absolute", false)? || path.is_absolute(),
                "path must be absolute"
            );
            normalized(&if path.is_absolute() {
                path.to_owned()
            } else {
                root.join(path)
            })?;
        }
        "root-state-paths" => {
            fields(0)?;
            keys(&["paths", "protected"])?;
            let paths = args
                .get("paths")
                .and_then(Value::as_array)
                .context("state paths missing")?;
            let protected = args
                .get("protected")
                .and_then(Value::as_array)
                .context("protected paths missing")?;
            ensure!(
                !paths.is_empty() && paths.len() <= 16 && protected.len() <= 256,
                "state path declaration exceeds bounds"
            );
            let mut resolved = Vec::new();
            for raw in paths {
                let spec: PathSpec = serde_json::from_value(raw.clone())?;
                let path = resolve(&spec, value, root)?;
                ensure!(
                    path != root && path != Path::new("/"),
                    "state cannot cover installation root"
                );
                for reserved in protected {
                    let reserved = root.join(relative(
                        reserved.as_str().context("protected path must be text")?,
                    )?);
                    ensure!(
                        !path.starts_with(&reserved) && !reserved.starts_with(&path),
                        "state overlaps protected installation path"
                    );
                }
                ensure!(
                    !resolved
                        .iter()
                        .any(|other: &PathBuf| path.starts_with(other) || other.starts_with(&path)),
                    "state roots overlap"
                );
                resolved.push(path);
            }
        }
        "path-relation" => {
            fields(0)?;
            keys(&[
                "parent",
                "child",
                "allow_child_subtree",
                "forbidden_child_first_component_prefixes",
            ])?;
            let parent: PathSpec =
                serde_json::from_value(args.get("parent").context("path parent missing")?.clone())?;
            let child: PathSpec =
                serde_json::from_value(args.get("child").context("path child missing")?.clone())?;
            let parent = resolve(&parent, value, root)?;
            let child = resolve(&child, value, root)?;
            ensure!(!parent.starts_with(&child), "parent cannot be inside child");
            if let Ok(relative) = child.strip_prefix(&parent) {
                ensure!(
                    flag("allow_child_subtree", false)?,
                    "child subtree is forbidden"
                );
                let first = relative
                    .components()
                    .next()
                    .and_then(|part| part.as_os_str().to_str())
                    .context("child relative component missing")?;
                let prefixes = args
                    .get("forbidden_child_first_component_prefixes")
                    .and_then(Value::as_array)
                    .context("forbidden prefixes missing")?;
                ensure!(
                    prefixes.len() <= 256
                        && prefixes.iter().all(|prefix| prefix
                            .as_str()
                            .is_some_and(|prefix| !first.starts_with(prefix))),
                    "child overlaps private namespace"
                );
            }
        }
        "external-web-override" => {
            fields(1)?;
            keys(&["development_pointer", "source_bound"])?;
            let development = candidate(text("development_pointer")?)?
                .as_bool()
                .context("development flag missing")?;
            ensure!(
                candidate(&rule.fields[0])?.is_null()
                    || development && !flag("source_bound", true)?,
                "external Web override is unavailable"
            );
        }
        "enum" => {
            fields(1)?;
            keys(&["values"])?;
            let values = args
                .get("values")
                .and_then(Value::as_array)
                .context("enum values missing")?;
            ensure!(
                !values.is_empty()
                    && values.len() <= 256
                    && values.iter().all(|value| matches!(
                        value,
                        Value::String(_) | Value::Number(_) | Value::Bool(_) | Value::Null
                    )),
                "invalid semantic enum"
            );
            ensure!(
                values.contains(candidate(&rule.fields[0])?),
                "semantic enum differs"
            );
        }
        "url" => {
            fields(1)?;
            keys(&[
                "allowed_schemes",
                "no_credentials",
                "no_query",
                "no_fragment",
                "loopback_host",
                "origin_only",
                "production_public_rtsps",
                "development_pointer",
                "relative_path",
            ])?;
            let input = candidate(&rule.fields[0])?
                .as_str()
                .context("URL must be text")?;
            ensure!(
                input.len() <= 65536 && !input.chars().any(char::is_control),
                "invalid URL text"
            );
            if flag("relative_path", false)? && input.starts_with('/') && !input.starts_with("//") {
                ensure!(
                    !input.contains(['?', '#']),
                    "relative URL contains query or fragment"
                );
                return Ok(());
            }
            let parsed = url::Url::parse(input)?;
            let schemes = args
                .get("allowed_schemes")
                .and_then(Value::as_array)
                .context("URL schemes missing")?;
            ensure!(
                !schemes.is_empty()
                    && schemes.len() <= 16
                    && schemes.iter().all(|scheme| scheme.is_string()),
                "invalid URL schemes"
            );
            let host = parsed.host().context("URL host missing")?;
            let loopback = match host {
                url::Host::Domain(host) => {
                    host.eq_ignore_ascii_case("localhost")
                        || host
                            .trim_matches(['[', ']'])
                            .parse::<std::net::IpAddr>()
                            .is_ok_and(|ip| ip.is_loopback())
                }
                url::Host::Ipv4(ip) => ip.is_loopback(),
                url::Host::Ipv6(ip) => ip.is_loopback(),
            };
            let unspecified = match host {
                url::Host::Domain(host) => host
                    .trim_matches(['[', ']'])
                    .parse::<std::net::IpAddr>()
                    .is_ok_and(|ip| ip.is_unspecified()),
                url::Host::Ipv4(ip) => ip.is_unspecified(),
                url::Host::Ipv6(ip) => ip.is_unspecified(),
            };
            ensure!(
                schemes
                    .iter()
                    .any(|scheme| scheme.as_str() == Some(parsed.scheme()))
                    && !(flag("no_credentials", false)?
                        && (!parsed.username().is_empty() || parsed.password().is_some()))
                    && !(flag("no_query", false)? && parsed.query().is_some())
                    && !(flag("no_fragment", false)? && parsed.fragment().is_some())
                    && !(flag("loopback_host", false)? && !loopback)
                    && !(flag("origin_only", false)? && !matches!(parsed.path(), "" | "/")),
                "URL violates current restrictions"
            );
            if flag("production_public_rtsps", false)? {
                let development = candidate(text("development_pointer")?)?
                    .as_bool()
                    .context("development flag missing")?;
                ensure!(
                    development || parsed.scheme() == "rtsps" && !loopback && !unspecified,
                    "production requires public RTSPS"
                );
            }
        }
        "string-bytes" => {
            fields(1)?;
            keys(&["minimum", "maximum"])?;
            let length = candidate(&rule.fields[0])?
                .as_str()
                .context("field must be text")?
                .len() as u64;
            ensure!(
                (number("minimum")?..=number("maximum")?).contains(&length),
                "string exceeds byte bound"
            );
        }
        "string-trim-no-control" => {
            fields(1)?;
            keys(&[])?;
            let actual = candidate(&rule.fields[0])?
                .as_str()
                .context("field must be text")?;
            ensure!(
                actual.trim() == actual && !actual.chars().any(char::is_control),
                "string violates canonical text"
            );
        }
        "object-value-string-bytes" => {
            fields(1)?;
            keys(&["minimum", "maximum"])?;
            for actual in candidate(&rule.fields[0])?
                .as_object()
                .context("field must be object")?
                .values()
            {
                let length = actual.as_str().context("object value must be text")?.len() as u64;
                ensure!(
                    (number("minimum")?..=number("maximum")?).contains(&length),
                    "object string exceeds byte bound"
                );
            }
        }
        "complete-string-set" => {
            fields(1)?;
            keys(&["values"])?;
            let expected = args
                .get("values")
                .and_then(Value::as_array)
                .context("complete values missing")?;
            let actual = candidate(&rule.fields[0])?
                .as_array()
                .context("field must be array")?;
            ensure!(
                actual.len() == expected.len()
                    && expected.iter().all(|value| actual
                        .iter()
                        .filter(|candidate| *candidate == value)
                        .count()
                        == 1),
                "string set incomplete or duplicated"
            );
        }
        _ => anyhow::bail!("required configuration semantic rule is not implemented"),
    }
    Ok(())
}

fn merge(defaults: &mut Value, supplied: &mut Value) -> anyhow::Result<()> {
    match (defaults, supplied) {
        (Value::Object(defaults), Value::Object(supplied)) => {
            for (key, mut value) in std::mem::take(supplied) {
                if let Some(default) = defaults.get_mut(&key) {
                    merge(default, &mut value)?;
                } else {
                    defaults.insert(key, value);
                }
            }
        }
        (default, supplied) => *default = std::mem::take(supplied),
    };
    Ok(())
}
